// Generated reference data for the starter library — do not edit by hand.
//
// Tenacity (t, hours on a smelling strip) = "substantivity" from The Good Scents Company
// (thegoodscentscompany.com), measured neat unless tAt (% dilution) is given. Materials TGSC has
// no figure for are left empty rather than guessed.
//
// IFRA (ifra, % in the finished product, Category 4 = fine fragrance) is read from the official
// IFRA Standards PDFs (ifrafragrance.org/standards/IFRA_STD_<nnn>.pdf) as published under the
// 51st Amendment (each standard keeps the amendment it was last revised in). Materials without an
// IFRA Standard of their own are left empty — they may still be restricted through constituents
// (e.g. citral, eugenol, geraniol in essential oils) — always check the supplier's IFRA certificate.

export interface SeedRef {
  t?: number
  tAt?: number
  ifra?: number
  ifraStd?: string
  ifraAmendment?: number
  ifraNote?: string
}

